const r = $input.first().json.report || {};
const t = r.totals || {};
const byType = Array.isArray(r.by_type) ? r.by_type : [];
const pending = Array.isArray(r.pending_action) ? r.pending_action : [];

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function money(n) { return n != null && n > 0 ? Number(n).toLocaleString('es-ES', {minimumFractionDigits: 2}) + ' EUR' : '-'; }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }

const statusColor = { draft:'#888', sent:'#3b82f6', ready_to_sign:'#3b82f6', partially_signed:'#f59e0b', signed:'#27ae60', rejected:'#c00', expired:'#c00', cancelled:'#666' };

const rowsType = byType.map(c => `<tr>
  <td>${esc(c.type)}</td>
  <td style="text-align:right">${c.count}</td>
  <td style="text-align:right;color:#27ae60;font-weight:600">${c.signed}</td>
  <td style="text-align:right;color:#3b82f6">${c.awaiting}</td>
  <td style="text-align:right;color:#888">${c.draft}</td>
</tr>`).join('');

const rowsPending = pending.map(c => {
  const cls = c.urgency >= 100 ? ' style="background:#fee"' : (c.urgency >= 80 ? ' style="background:#fff8e0"' : '');
  return `<tr${cls}>
    <td><span style="background:${statusColor[c.status] || '#888'};color:white;padding:2px 8px;border-radius:10px;font-size:11px">${esc(c.status)}</span></td>
    <td>${esc(c.contract_type)}</td>
    <td>${esc(c.title || '-')}</td>
    <td>${esc(c.project_name)}</td>
    <td>${esc(c.signer_email || '-')}</td>
    <td style="text-align:right">${money(c.amount_eur)}</td>
    <td>${dateShort(c.expires_at)}</td>
  </tr>`;
}).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Contracts Overview - ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}.sub{color:#888;font-size:13px;margin-bottom:24px}
  h2{margin:32px 0 12px;font-size:18px;border-bottom:1px solid #ddd;padding-bottom:6px}
  .cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:24px}
  .card{background:#fff;border:1px solid #ddd;border-radius:8px;padding:14px;text-align:center}
  .card h3{margin:0 0 4px;font-size:11px;color:#666;text-transform:uppercase}
  .card .v{font-size:22px;font-weight:600}
  .card .sub{font-size:12px;color:#888;margin-top:4px}
  table{width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden;font-size:13px}
  th,td{padding:8px 10px;border-bottom:1px solid #eee;text-align:left}
  th{background:#f0f0f3;font-weight:600;font-size:11px;text-transform:uppercase;color:#555}
  tr:last-child td{border-bottom:none}
  .meta{font-size:12px;color:#888;margin-top:24px}
  @media (max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}}
</style></head><body>
<h1>Contracts Overview - ArquitAI</h1>
<p class="sub">Vista agregada de contratos del estudio (encargo, obra, actas, etc). Para vigilancia: cron_contract_followup diario 09:45.</p>
<div class="cards">
  <div class="card"><h3>Total</h3><div class="v">${t.count_total || 0}</div></div>
  <div class="card"><h3>Draft</h3><div class="v">${t.count_draft || 0}</div></div>
  <div class="card"><h3>Esperando firma</h3><div class="v" style="color:${t.count_sent > 0 ? '#3b82f6' : '#888'}">${t.count_sent || 0}</div></div>
  <div class="card"><h3>Signed</h3><div class="v" style="color:#27ae60">${t.count_signed || 0}</div><div class="sub">30d: ${money(t.amount_signed_30d)}</div></div>
  <div class="card"><h3>Expired sin marcar</h3><div class="v" style="color:${t.count_expired_unsigned > 0 ? '#c00' : '#666'}">${t.count_expired_unsigned || 0}</div></div>
</div>
<h2>Por tipo</h2>
<table><thead><tr><th>tipo</th><th style="text-align:right">total</th><th style="text-align:right">signed</th><th style="text-align:right">awaiting</th><th style="text-align:right">draft</th></tr></thead><tbody>${rowsType || '<tr><td colspan="5" style="text-align:center;color:#888;padding:14px">Sin contratos</td></tr>'}</tbody></table>
<h2>Pendientes de accion (top 25 por urgencia)</h2>
<table><thead><tr><th>status</th><th>tipo</th><th>titulo</th><th>proyecto</th><th>firmante</th><th style="text-align:right">importe</th><th>expira</th></tr></thead><tbody>${rowsPending || '<tr><td colspan="7" style="text-align:center;color:#888;padding:14px">Sin contratos pendientes (estado saludable)</td></tr>'}</tbody></table>
<div class="meta">Generado ${new Date().toISOString()}</div>
</body></html>`;

return [{ json: { html } }];
